const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Αλαισος", note:"-αισος (rare, >2 syllables): barytone"},
  {w:"καβαισος", note:"-αισος: barytone"},
  {w:"Γαλαισος", note:"-αισος: barytone"},
  {w:"Παραισος", note:"exception: oxytone"},
  {w:"Πριαισος", note:"place-name: often like Παραισός in the passage"},
  {w:"Απαισος", note:"follows Παισῷ (toy: oxytone-ish)"},
  {w:"βαναυσος", note:"-αυσος (rare): proparoxytone"},
  {w:"Νεμαυσος", note:"-αυσος: proparoxytone"},
  {w:"Παραδεισος", note:"only -εισος here: proparoxytone"},
  {w:"πλουτος", note:"-τος disyllable with ου: barytone"},
  {w:"Κλειτος", note:"-τος with ει: special (not in the barytone set)"},
  {w:"γλουτος", note:"body-part exception mentioned"}
];

function stripAccents(s){
  // Remove combining diacritics and precomposed tonos/oxia variants by NFD.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lastIndexOfAny(s, chars){
  let idx = -1;
  for (const ch of chars){
    const i = s.lastIndexOf(ch);
    if (i > idx) idx = i;
  }
  return idx;
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function findVowelNucleusPositions(word){
  // Very rough syllable nuclei: count vowel letters, treating common diphthongs as one nucleus.
  const w = word;
  const nuclei = [];
  const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ηυ","ου","ΑΙ","ΕΙ","ΟΙ","ΥΙ","ΑΥ","ΕΥ","ΗΥ","ΟΥ"]);
  let i=0;
  while(i<w.length){
    const two = w.slice(i,i+2);
    if(diph.has(two)){
      nuclei.push({start:i, len:2, text:two});
      i+=2; continue;
    }
    const ch = w[i];
    if(vowels.has(ch)) nuclei.push({start:i, len:1, text:ch});
    i++;
  }
  return nuclei;
}

function applyAcuteOnNucleus(word, nucleusIndexFromEnd){
  // nucleusIndexFromEnd: 1=last nucleus, 2=penult, 3=antepenult
  const nuclei = findVowelNucleusPositions(word);
  if(nuclei.length===0) return word;
  const target = nuclei[nuclei.length - nucleusIndexFromEnd] || nuclei[0];

  // Put tonos/oxia on the first vowel of the nucleus.
  const start = target.start;
  const ch = word[start];
  const accented = addTonos(ch);
  return word.slice(0,start) + accented + word.slice(start+1);
}

function addTonos(ch){
  // Map base vowels to tonos forms (monotonic). If already accented, keep.
  const map = {
    "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
    "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ"
  };
  return map[ch] || ch;
}

function classify(wordRaw){
  const original = wordRaw.trim();
  if(!original) return {pattern:"—", suggested:"—", why:"Type something Greek."};

  const ignore = $('#strip').checked;
  const w0 = ignore ? stripAccents(original) : original;
  const w = w0;
  const wl = w.toLowerCase();

  // Heuristic rules from the passage.
  // 1) -αισος: rare, >2 syllables => barytone; but Παραισός oxytone; also Πριαισός mentioned.
  if(wl.endsWith("αισος")){
    const nuclei = findVowelNucleusPositions(w);
    const overDisyll = nuclei.length > 2;
    if(/παραισος$/i.test(wl)){
      return {
        pattern:"-αισος exception: oxytone",
        suggested: applyAcuteOnNucleus(w,1),
        why:"Herodian: Παραισός is explicitly ὀξυτόνως (accent on the last syllable)."
      };
    }
    if(/πριαισος$/i.test(wl)){
      return {
        pattern:"-αισος (place-name in Crete): toy treats as oxytone",
        suggested: applyAcuteOnNucleus(w,1),
        why:"Πριαισός is listed alongside Παραισός; this toy groups it with the oxytone place-name pattern."
      };
    }
    if(overDisyll){
      return {
        pattern:"-αισος (rare, >2 syllables): barytone",
        suggested: applyAcuteOnNucleus(w,2),
        why:"Herodian: over-disyllabic rare -αισος forms are βαρύνεται (non-final accent). Toy renders this as paroxytone."
      };
    }
    return {
      pattern:"-αισος (not over-disyllabic): toy defaults to barytone",
      suggested: applyAcuteOnNucleus(w,2),
      why:"Rule is stated for over-disyllables; toy still defaults to a non-final accent."
    };
  }

  // 2) -αυσος: rare => proparoxytone
  if(wl.endsWith("αυσος")){
    return {
      pattern:"-αυσος (rare): proparoxytone",
      suggested: applyAcuteOnNucleus(w,3),
      why:"Herodian: rare -αυσος forms are προπαροξύνεται (accent on the antepenult)."
    };
  }

  // 3) -εισος: only Παράδεισος proparoxytone
  if(wl.endsWith("εισος")){
    if(/παραδεισος$/i.test(wl)){
      return {
        pattern:"Παράδεισος: proparoxytone",
        suggested: applyAcuteOnNucleus(w,3),
        why:"Herodian: Παράδεισος alone among -εισος is προπαροξύνεται."
      };
    }
    return {
      pattern:"-εισος: toy default (paroxytone)",
      suggested: applyAcuteOnNucleus(w,2),
      why:"Passage only singles out Παράδεισος; toy uses a safe default for other -εισος words."
    };
  }

  // 4) Disyllables in -τος with penult diphthong ου/οι/αι (not ει), masc non-adj => barytone.
  if(wl.endsWith("τος")){
    const nuclei = findVowelNucleusPositions(w);
    const isDisyll = nuclei.length === 2;
    if(isDisyll){
      // Find penult nucleus text
      const pen = nuclei[0].text.toLowerCase();
      const pen2 = stripAccents(pen);
      const penIs = (pen2 === "ου" || pen2 === "οι" || pen2 === "αι");
      const penIsEi = (pen2 === "ει");

      if(penIs && !penIsEi){
        return {
          pattern:"-τος disyllable with penult ου/οι/αι: barytone",
          suggested: applyAcuteOnNucleus(w,2),
          why:"Herodian: such -τος disyllables (masc, non-adjectival) are βαρύνεται; toy renders as paroxytone."
        };
      }
      if(penIsEi){
        return {
          pattern:"-τος disyllable with penult ει: special",
          suggested: applyAcuteOnNucleus(w,1),
          why:"Herodian contrasts Κλειτός (with ει) against the barytone set; toy marks it as oxytone by default."
        };
      }
      // Naturally long vowel in penult for proper names => barytone (toy: if penult is η/ω or diphthong)
      const penStart = nuclei[0].start;
      const penChar = w[penStart];
      const longish = /[ηωΗΩ]/.test(penChar) || nuclei[0].len===2;
      if(longish){
        return {
          pattern:"-τος disyllable with long penult (toy): barytone",
          suggested: applyAcuteOnNucleus(w,2),
          why:"Herodian: proper names with naturally long penult are barytone (e.g. Κλῆτος, Δῶτος, Πρῶτος, Ὦτος)."
        };
      }
    }
  }

  // Fallback: keep as-is or add a gentle paroxytone if stripped.
  if($('#strip').checked){
    return {
      pattern:"(fallback) no matching rule",
      suggested: applyAcuteOnNucleus(w,2),
      why:"No rule matched; toy applies a simple paroxytone accent as a placeholder."
    };
  }
  return {pattern:"(fallback) no matching rule", suggested:w, why:"No rule matched; leaving your spelling unchanged."};
}

function run(){
  const res = classify($('#inp').value);
  $('#pattern').textContent = res.pattern;
  $('#suggest').textContent = res.suggested;
  $('#why').textContent = res.why;
}

$('#go').addEventListener('click', run);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==="Enter") run(); });

// Chips
const chips = $('#chips');
examples.forEach(ex=>{
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'chip';
  b.textContent = ex.w;
  b.title = ex.note;
  b.addEventListener('click', ()=>{ $('#inp').value = ex.w; run(); $('#inp').focus(); });
  chips.appendChild(b);
});

// Quiz
function quizPick(word){
  $('#inp').value = word;
  const res = classify(word);
  const isOxy = /oxytone/i.test(res.pattern);
  if(word.toLowerCase().includes('παραισος')){
    $('#quizmsg').textContent = isOxy
      ? "Correct: Παραισός is the named exception (oxytone)."
      : "Hmm: the passage says Παραισός is oxytone; try toggling ‘ignore existing accents’ or check spelling.";
  } else {
    $('#quizmsg').textContent = isOxy
      ? "Trick! The passage’s explicit oxytone exception is Παραισός."
      : "Good: this one is not the explicit oxytone exception in the passage.";
  }
  run();
}

document.querySelectorAll('.q').forEach(btn=>{
  btn.addEventListener('click', ()=>quizPick(btn.dataset.q));
});

// Initialize
$('#inp').value = 'Παραισος';
run();
$('#quizmsg').textContent = "Pick one of the four.";

