// Quiz
function quizPick(word){
  $('#inp').value = word;
  const res = classify(word);
  const isOxy = /oxytone/i.test(res.pattern);
  if(word.toLowerCase().includes('παραισος')){
    $('#quizmsg').textContent = isOxy
      ? "Correct: Παραισός is the named exception (oxytone)."
      : "Hmm: the passage says Παραισός is oxytone; try toggling ‘ignore existing accents’ or check spelling.";
  } else {
    $('#quizmsg').textContent = isOxy
      ? "Trick! The passage’s explicit oxytone exception is Παραισός."
      : "Good: this one is not the explicit oxytone exception in the passage.";
  }
  run();
}

document.querySelectorAll('.q').forEach(btn=>{
  btn.addEventListener('click', ()=>quizPick(btn.dataset.q));
});

